let project=null,db,screen='boundary',subtab='board',selectedInterface='',selectedSession='',selectedArtifact='',selectedBaseline='',previewReport=false,reportExcerpts=false,viewHex=false,placing=false,query='',saveQueue=Promise.resolve(),serial=null,saveState='Saved locally';
