const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${ICONS[n]||ICONS.file}"/></svg>`;
const button=(label,action,cls='',ico='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const tag=(s,cls='')=>`<span class="tag ${cls||String(s).toLowerCase().replaceAll(' ','-')}">${esc(s)}</span>`;
const date=s=>{try{return new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}catch{return s}};
const list=k=>project?project[k].filter(x=>x.deviceId===project.deviceId):[];
