const empty=(title,copy,action='')=>`<div class="empty">${icon('file')}<h3>${title}</h3><p>${copy}</p>${action}</div>`;
function notify(message){if(modal.open){let status=modal.querySelector('.dialog-status');if(!status){status=document.createElement('p');status.className='notice spaced dialog-status';status.setAttribute('role','status');modal.querySelector('.dialog-body').append(status);}status.textContent=message;}$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000)}
function settingsApply(){document.documentElement.dataset.theme=prefs.theme;document.body.classList.toggle('advanced',prefs.advanced);try{localStorage.setItem('probe-prefs',JSON.stringify(prefs))}catch{}}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('probe-workbench',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function readState(){return new Promise((resolve,reject)=>{const t=db.transaction('state','readonly');const r=t.objectStore('state').get('project');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function updateSave(){const el=$('#save-state');if(el)el.innerHTML=`<span class="dot" style="${saveState.includes('failed')?'background:var(--red)':''}"></span>${esc(saveState)}`;}
function save(){if(!project)return Promise.resolve();project.updatedAt=now();project.version=VERSION;const revision=++saveRevision;const copy=structuredClone(project);saveState='Saving…';updateSave();saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('Local storage is unavailable. Export your project to preserve work.'));const t=db.transaction('state','readwrite');t.objectStore('state').put(copy,'project');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Save interrupted.'));})).then(()=>{saveState=revision===saveRevision?'Saved locally':'Unsaved capture…';updateSave()}).catch(e=>{saveState='Save failed · export project';updateSave();notify(e.message||'Local save failed. Export your project.');});return saveQueue}
function changed(message){save();render();if(message)notify(message)}
function download(name,content,mime='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;(modal.open?modal:document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function safeName(s){return String(s).replace(/[^a-z0-9._-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,100)||'probe'}
function pick(accept,onfile){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{if(input.files[0]){try{await onfile(input.files[0])}catch(e){notify(e.message)}}};input.click()}
async function bytesData(bytes,mime){return await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('File could not be read.'));r.readAsDataURL(new Blob([bytes],{type:mime}))})}
async function evidenceFromFile(file,kind,notes='',targetDevice=project.deviceId,computedHash=null){if(file.size>32*1024*1024)throw Error('Use a file of 32 MiB or less. Larger acquisitions can be referenced in a note.');if(project.evidence.reduce((a,e)=>a+(e.size||0),0)+file.size>128*1024*1024)throw Error('This project has reached the 128 MiB evidence limit. Export it and begin another assessment.');const bytes=new Uint8Array(await file.arrayBuffer());return {id:uid('ev'),deviceId:targetDevice,title:file.name,kind,mime:file.type||'application/octet-stream',data:await bytesData(bytes,file.type||'application/octet-stream'),hash:computedHash||await sha256(bytes),size:file.size,createdAt:now(),source:'User-supplied file',tool:'Unspecified',conditions:'Unspecified',notes};}
async function textEvidence(title,text,kind='Observation',meta={}){const file=new File([text],title+'.txt',{type:'text/plain'});const e=await evidenceFromFile(file,kind);Object.assign(e,{title,...meta});project.evidence.push(e);return e}
function rawText(e){try{const b=Uint8Array.from(atob(e.data.split(',')[1]),c=>c.charCodeAt(0));return new TextDecoder().decode(b)}catch{return ''}}
function evidenceChecks(ids=[]){return `<div class="checklist">${list('evidence').map(e=>`<label><input type="checkbox" name="evidenceIds" value="${esc(e.id)}" ${ids.includes(e.id)?'checked':''}> <span>${esc(e.title)} <span class="muted">· ${esc(e.kind)}</span></span></label>`).join('')||'<span class="muted smalltext">No evidence yet. Add a note or import a file first.</span>'}</div>`}
function field(label,name,value='',type='text',full=false){return `<label class="field ${full?'full':''}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${['title','name','label'].includes(name)?'required':''}></label>`}
function area(label,name,value='',full=true){return `<label class="field ${full?'full':''}">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function selectField(label,name,options,value,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}
function showDialog(title,body,onSubmit=null,submit='Save',extra=''){
 modal.innerHTML=`<form id="dialog-form"><div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('','close','ghost','close','aria-label="Close dialog"')}</div><div class="dialog-body">${body}<div class="form-error" role="alert" id="form-error"></div></div><div class="dialog-actions">${extra}${button(onSubmit?'Cancel':'Close','close')}${onSubmit?`<button class="primary" type="submit">${submit}</button>`:''}</div></form>`;
 if(!modal.open)modal.showModal();$('#dialog-form').onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const form=e.currentTarget;const data=new FormData(form);const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await onSubmit(data);modal.close()}catch(err){$('#form-error').textContent=err.message;btn.disabled=false}};
}
