function render(){settingsApply();app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div class="brand-copy"><div class="brand-name">PROBE</div><div class="brand-sub">FIELD INSTRUMENT / 01</div></div></div><div class="nav-label">ASSESSMENT WORKSPACE</div><nav aria-label="Workspaces">${NAV.map(([id,name,desc])=>`<button class="nav-btn ${screen===id?'active':''}" data-action="nav" data-id="${id}" aria-label="${name}: ${desc}" ${screen===id?'aria-current="page"':''}>${icon(id)}<span class="nav-copy"><strong>${name}</strong><span>${desc}</span></span></button>`).join('')}</nav><div class="sidebar-bottom"><strong>GREEN SHOE GARAGE</strong><span>Observations become evidence.<br>Local-first · no telemetry<br>PROBE v${VERSION}</span><div class="sidebar-tools">${button('','preferences','small','settings','aria-label="Preferences" title="Preferences"')}${button('','companion-status','small','network','aria-label="Companion status" title="Companion status"')}${button('','help','small','help','aria-label="Help and roadmap" title="Help and roadmap"')}${button('','project','small','file','aria-label="Project options" title="Project options"')}</div></div></aside><div class="main-shell"><header class="topbar"><div><div class="project-name">${esc(project?.title||'Embedded security workbench')}</div><div id="save-state" class="save-state"><span class="dot"></span>${project?esc(saveState):'Your assessment stays on this device'}</div></div><div class="row"><button class="mobile-menu small" data-action="preferences" aria-label="Preferences">${icon('settings')}</button>${project?`<label class="row"><span class="sr-only" hidden>Selected device</span><select id="device-select" aria-label="Selected device">${project.devices.map(d=>`<option value="${esc(d.id)}" ${d.id===project.deviceId?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label>${button('','project','small','file','aria-label="Project options" title="Project options"')}${button('','export','small','download','aria-label="Export project JSON" title="Export project JSON"')}${button('<span class="report-label">Report</span>','report','primary small','report','aria-label="Report"')}`:button('Import project','import-project','small','upload')}</div></header><main id="main" class="content" tabindex="-1">${project?workspace():welcome()}</main></div></div>`;
 const sel=$('#device-select');if(sel)sel.onchange=async()=>{if(serial){notify('Disconnect serial capture before changing the device.');sel.value=project.deviceId;return}project.deviceId=sel.value;selectedInterface=selectedSession=selectedArtifact=selectedBaseline='';changed()};
 if(project&&screen==='boottrace')updateTerminal();
}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${description}</p></div><div class="row">${actions}</div></div>`}
function context(){const d=device();return `<div class="contextbar">${tag(project.sample?'SAMPLE ASSESSMENT':'LOCAL ASSESSMENT',project.sample?'warn':'')}<strong>${esc(d.name)}</strong><span class="divider"></span><span class="muted">${esc(d.model||'Model not recorded')}</span><span class="divider"></span><span class="mono smalltext">FW ${esc(d.firmware||'unknown')}</span><span style="margin-left:auto">${button('Device details','device','small ghost','edit')}</span></div>`}
function workspace(){if(previewReport)return `<div class="row between wrap" style="margin-bottom:20px">${button('Back to workspace','report-back','','arrow')}${button('Print / Save as PDF','print','primary','report')}</div><article class="report-paper">${reportBody(reportExcerpts)}</article>`;const views={boundary:boundaryView,boottrace:bootView,firmglass:firmView,network:networkView,assessment:assessmentView};return views[screen]()+`<footer class="footer-note"><span>PROBE v${VERSION} · ${prefs.advanced?'Advanced':'Easy'} mode · ${navigator.onLine?'Local workspace':'Offline workspace'}</span><span>${button('Help & capabilities','help','small ghost','help')}</span></footer>`}
function boardSvg(){return `<svg class="board" viewBox="0 0 700 420" role="img" aria-label="Illustrative circuit board. Use an actual board photograph for measured locations."><defs><pattern id="grid" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#ffffff20"/></pattern></defs><rect x="74" y="60" width="550" height="300" rx="14" fill="#326b49" stroke="#275739" stroke-width="3"/><rect x="74" y="60" width="550" height="300" rx="14" fill="url(#grid)"/><g fill="none" stroke="#8bb97b" stroke-width="3" opacity=".65"><path d="M187 294h65V230h46 M190 283h50V216h58 M422 144h73v-34h65 M420 156h85v-32h55 M405 243h32v43h92 M405 255h20v43h104 M198 151h48v40h52 M200 163h35v41h63 M350 278v44h-77 M364 278v31h-78"/></g><g fill="#ead7a0">${[0,1,2,3,4,5,6,7].map(i=>`<rect x="${302+i*13}" y="137" width="7" height="17"/><rect x="${302+i*13}" y="264" width="7" height="17"/><rect x="280" y="${160+i*13}" width="17" height="7"/><rect x="406" y="${160+i*13}" width="17" height="7"/>`).join('')}</g><rect x="296" y="151" width="111" height="114" rx="4" fill="#1c3027" stroke="#a8baa0"/><text x="351" y="202" text-anchor="middle" fill="#bac8b7" font-size="14" font-family="monospace">MCU / SoC</text><text x="351" y="224" text-anchor="middle" fill="#92a58d" font-size="9" font-family="monospace">DEVICE UNDER TEST</text><circle cx="307" cy="162" r="3" fill="#d8e4c6"/><rect x="63" y="123" width="123" height="88" rx="4" fill="#cbd2c4" stroke="#748775" stroke-width="3"/><rect x="62" y="133" width="25" height="67" fill="#718575"/><text x="124" y="173" text-anchor="middle" font-size="11" fill="#40584a" font-family="monospace">ETHERNET</text><rect x="502" y="241" width="84" height="72" fill="#c7cfbf" stroke="#8c9e87" stroke-width="3"/><text x="544" y="279" text-anchor="middle" fill="#53674f" font-size="11" font-family="monospace">RADIO</text><path d="M562 239v-25h-17v-17h28v-17h-28" stroke="#e3d18c" stroke-width="3" fill="none"/><rect x="405" y="273" width="44" height="34" rx="2" fill="#1b3024"/>${[0,1,2,3].map(i=>`<path d="M400 ${279+i*7}h7 M447 ${279+i*7}h7" stroke="#d3d7af" stroke-width="4"/>`).join('')}<g fill="#e9d997" stroke="#212e22" stroke-width="3">${[0,1,2,3].map(i=>`<circle cx="${155+i*18}" cy="301" r="5"/>`).join('')}${[0,1,2,3].map(i=>`<circle cx="${483+i*18}" cy="121" r="5"/>`).join('')}</g><text x="154" y="328" fill="#d6e2c5" font-size="10" font-family="monospace">CONSOLE</text><text x="477" y="100" fill="#d6e2c5" font-size="10" font-family="monospace">DEBUG</text><g fill="#b6c39e" stroke="#1a452d" stroke-width="4">${[[90,76],[608,76],[90,344],[608,344]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6"/>`).join('')}</g><text x="100" y="96" fill="#d6e2c5" font-size="9" letter-spacing="2" font-family="monospace">PROBE / BENCH REFERENCE</text><text x="525" y="344" fill="#bacda4" font-size="9" font-family="monospace">NOT TO SCALE</text></svg>`}
function welcome(){return `<div class="welcome"><div class="welcome-hero"><div><div class="eyebrow">GREEN SHOE GARAGE · FIELD INSTRUMENT</div><h1>Put a device<br>on the bench.</h1><p>Follow the evidence from circuit board to firmware, from first boot to final report. One connected workspace for embedded security assessment.</p><div class="row">${button('New assessment','new','primary','plus')}${button('Explore sample','sample','','arrow')}</div><div class="smalltext" style="margin-top:20px;color:#a9c49e">Local-first. Offline-capable. No account required in the portable edition.</div></div><div class="welcome-art" style="position:relative;min-height:280px">${boardSvg()}</div></div><div class="three-col spaced"><div class="panel feature"><div class="eyebrow">01 / UNDERSTAND</div><h2>Map the attack surface.</h2><p>Keep components, interfaces and trust boundaries attached to the device they describe.</p></div><div class="panel feature"><div class="eyebrow">02 / INVESTIGATE</div><h2>Follow the observation.</h2><p>Capture serial output. Inspect firmware bytes. Bring existing tool results into the same assessment.</p></div><div class="panel feature"><div class="eyebrow">03 / VERIFY</div><h2>Make the finding defensible.</h2><p>Link evidence, record confidence, freeze a baseline and verify what changed.</p></div></div><p class="muted smalltext" style="text-align:center;margin:24px">Your first action creates a clean project. The fictional sample is loaded only when you choose it.</p></div>`}
function boundaryView(){const interfaces=list('interfaces');if(!interfaces.some(x=>x.id===selectedInterface))selectedInterface=interfaces[0]?.id||'';const item=interfaces.find(x=>x.id===selectedInterface);const d=device();return heading('01 / BOUNDARY','Know the device.','Map interfaces, record what you know, and make uncertainty visible.',button('Add interface','interface','primary','plus'))+context()+`<div class="boundary-grid"><section class="panel"><div class="panel-head"><h2>Device map</h2><div class="row">${button('Board photo','photo','small','upload')}${d.photo?button('Reset photo','clear-photo','small'):''}</div></div><div class="tabs">${['board','connections'].map(t=>button(t==='board'?'Board & interfaces':'System connections','boundary-tab',t===subtab?'active':'','',`data-id="${t}"`)).join('')}</div>${subtab==='board'?`<div class="board-wrap ${placing?'placing':''}" id="board-map">${d.photo?`<img src="${esc(d.photo)}" alt="Board photograph of ${esc(d.name)}">`:boardSvg()}<div class="board-overlay">${interfaces.map((x,i)=>`<button class="pin ${x.id===selectedInterface?'selected':''}" data-action="select-interface" data-id="${esc(x.id)}" style="left:${Number(x.x)||50}%;top:${Number(x.y)||50}%" title="${esc(x.label)}" aria-label="Inspect ${esc(x.label)}">${i+1}</button>`).join('')}</div></div><div class="board-caption"><span>${d.photo?'USER-SUPPLIED PHOTOGRAPH':'ILLUSTRATIVE BOARD · NOT A DEVICE IDENTIFICATION'}</span><span>${interfaces.length} INTERFACES</span></div><div class="interface-strip">${interfaces.map((x,i)=>button(`${i+1} · ${esc(x.label)}`,'select-interface',`small ${x.id===selectedInterface?'active':''}`,'',`data-id="${esc(x.id)}"`)).join('')||'<span class="muted smalltext">Add an interface to begin annotating the device.</span>'}</div>`:connectionsView()}</section><aside class="panel inspector"><div class="panel-head"><h2>Interface inspector</h2>${item?button('','interface-edit','small ghost','edit','aria-label="Edit selected interface"'):''}</div><div class="panel-body">${item?`<div class="row between">${tag(item.type)}${tag(item.status,item.status==='Suspected'?'warn':'')}</div><h3 class="inspector-title">${esc(item.label)}</h3><dl class="detail-list"><dt>Pin assignment</dt><dd>${esc(item.pins||'Not recorded')}</dd><dt>Logic level</dt><dd>${esc(item.voltage||'Not measured')}</dd><dt>Evidence</dt><dd>${(item.evidenceIds||[]).length} linked items</dd></dl><p class="muted smalltext" style="line-height:1.8">${esc(item.notes||'No notes yet.')}</p><div class="stack spaced">${button('Observe this interface','observe-interface','primary','boottrace')}${button('Record evidence','evidence-note','','plus')}${button(placing?'Click a location on the map':'Place marker on map','place-marker','small','boundary')}</div><p class="muted smalltext spaced">${item.status==='Suspected'?'This identification is provisional. Verify it before drawing a conclusion.':'Measured values and test conditions belong with the evidence.'}</p>`:empty('Select an interface','Add a connector, component or radio, then inspect its details here.')}</div></aside></div><div class="two-col spaced"><section class="panel"><div class="panel-head"><h2>Evidence on the bench</h2>${button('All evidence','evidence','small','arrow')}</div><div class="panel-body">${evidenceRows(list('evidence').slice(-3).reverse())}</div></section><section class="panel"><div class="panel-head"><h2>Assessment scope</h2>${button('Edit scope','scope','small','edit')}</div><div class="panel-body"><p class="scope-text">${esc(project.scope||'Record the included devices, interfaces, test environment and access level.')}</p><div class="row between spaced"><span class="muted smalltext">${count('assumptions')} assumptions · ${count('findings')} findings</span>${button('Assumptions','assumptions','small')}</div></div></section></div>`}
function connectionsView(){return `<div class="panel-body"><div class="row between"><p class="muted smalltext">Document the interfaces between systems.</p>${button('Add connection','connection','small','plus')}</div></div>${list('connections').length?`<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Protocol</th><th>Trust boundary</th><th></th></tr></thead><tbody>${list('connections').map(x=>`<tr><td><strong>${esc(x.from)}</strong> → ${esc(x.to)}<span class="sub">${esc(x.notes)}</span></td><td>${esc(x.protocol)}</td><td>${esc(x.boundary)}</td><td>${button('Edit','connection','small','',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Connect the system','Add the gateway, application, workstation or service that exchanges data with this device.')}`}
function evidenceRows(items){return items.map(e=>`<div class="info-line"><div class="item-icon">${icon(e.kind==='Serial log'?'boottrace':'file')}</div><div class="body"><strong>${esc(e.title)}</strong><p>${esc(e.kind)} · ${date(e.createdAt)}</p></div>${button('View','evidence-detail','small ghost','',`data-id="${e.id}"`)}</div><div class="mode-advanced evidence-provenance"><strong>Acquisition:</strong> ${esc(e.source||'Unspecified')} · ${esc(e.tool||'Unspecified')}<br>${esc(e.conditions||'Conditions not recorded')}<br><span class="hash">SHA-256 ${esc(e.hash)}</span></div>`).join('')||empty('No evidence yet','Capture an observation or import a file to preserve its original and hash.',button('Add evidence','evidence','small','plus'))}
function currentSession(){return list('sessions').find(s=>s.id===selectedSession)}
function bootView(){return `<div class="tabs" aria-label="Observation mode">${button('Serial capture','boot-tab',bootTab==='serial'?'active':'','','data-id="serial"')}${button('Debugger','boot-tab',bootTab==='debug'?'active':'','','data-id="debug"')}</div>`+(bootTab==='serial'?serialView():heading('02 / BOOTTRACE','Observe the running target.','Structured debugger controls and memory evidence.', '')+context()+debuggerUI.view());}
function serialView(){
 const sessions=list('sessions');if(!sessions.some(x=>x.id===selectedSession))selectedSession=sessions[0]?.id||'';
 const s=currentSession(),live=serial?.session.id===s?.id,canSend=live&&serial.state==='connected'&&!serial.stopReason;
 return heading('02 / BOOTTRACE','Every byte. In context.','Connect → capture → inspect → preserve.',button('Import session','import-session','','upload')+button('Connection settings','serial-profile','','settings')+button(serial?'Disconnect':'Connect serial',serial?'disconnect':'connect','primary','boottrace',serial?.state==='stopping'?'disabled':''))+context()+`
 <div class="session-grid"><section class="panel"><div class="panel-head"><h2>Sessions</h2>${tag(sessions.length)}</div><div class="session-list">${sessions.map(x=>`<button class="session-button ${x.id===selectedSession?'active':''}" data-action="select-session" data-id="${x.id}"><strong>${esc(x.label)}</strong><small>${date(x.createdAt)} · <span data-session-count="${x.id}">${x.lines.length}</span> records${serial?.session.id===x.id?' · LIVE':''}</small></button>`).join('')||'<div class="panel-body smalltext muted">Connect an adapter or import a session to start.</div>'}</div></section>
 <section class="panel serial-panel"><div class="panel-head wrap"><div><h2>${esc(s?.label||'Serial observation')}</h2><p class="muted smalltext spaced-small">${s?.options?esc(optionsLabel(s.options)):'Imported text logs retain their original evidence.'}</p></div>${tag(live?serial.state.toUpperCase():(s?.status||'IMPORTED / DISCONNECTED').toUpperCase(),live?'passed':'')}</div>
 <div class="toolbar serial-toolbar"><input id="log-search" type="search" placeholder="Search complete lines or byte records…" aria-label="Filter captured output" value="${esc(query)}"><label class="sr-only" for="serial-direction">Direction</label><select id="serial-direction" aria-label="Direction">${['all','RX','TX'].map(v=>`<option value="${v}" ${directionFilter===v?'selected':''}>${v==='all'?'All directions':v}</option>`).join('')}</select>${button(viewHex?'Hex records':'Text lines','toggle-hex','small')}${button('Bookmark','event','small','clock',!s?'disabled':'')}</div>
 <div class="serial-stats smalltext" id="serial-stats"></div><div id="terminal" class="terminal" role="log" tabindex="0" aria-label="Serial output" aria-live="off"></div>
 <div class="serial-view-controls"><label><input id="show-tx" type="checkbox" ${showTx?'checked':''}> Show local TX echo</label><label><input id="follow-output" type="checkbox" ${followOutput?'checked':''}> Follow output</label><span>UTF-8 text · control bytes escaped · host timestamps</span></div>
 <form class="serial-composer" id="serial-send"><div class="row wrap"><label>Send as <select id="send-mode" aria-label="Transmit format"><option value="text" ${serialDraft.mode==='text'?'selected':''}>Text (UTF-8)</option><option value="hex" ${serialDraft.mode==='hex'?'selected':''}>Hex bytes</option></select></label><label>Ending <select id="send-ending" aria-label="Line ending" ${serialDraft.mode==='hex'?'disabled':''}>${['none','LF','CR','CRLF'].map(v=>`<option ${serialDraft.ending===v?'selected':''}>${v}</option>`).join('')}</select></label>${button('History','serial-history','small','clock',!device()?.serialHistory?.length?'disabled':'')}<span class="muted smalltext">${serialDraft.mode==='hex'?'Hex sends exactly the entered bytes.':'A blank message can send only a line ending.'}</span></div>
 <div class="row spaced-small"><input id="serial-command" aria-label="Serial data to send" value="${esc(serialDraft.value)}" maxlength="16384" autocomplete="off" spellcheck="false" placeholder="${serialDraft.mode==='hex'?'00 FF 0D 0A':'Prepare text to send'}"><button id="send-button" class="primary" type="submit" ${!canSend?'disabled':''}>Send</button></div>
 <div id="send-preview" class="send-preview mono" role="status"></div><p class="muted smalltext">${canSend?'Sends go to this live session. Commands are never replayed on reconnect.':serial?'Select the live session to transmit.':'Drafts can be prepared here. Connect an adapter to transmit.'}</p></form>
 <div class="toolbar wrap">${button('Compare sessions','compare-sessions','small','',sessions.length<2?'disabled':'')}${button('Save evidence','session-evidence','small','file',!s?'disabled':'')}${button('Export session','session-download','small','download',!s?'disabled':'')}</div></section></div>
 <div class="two-col spaced"><section class="panel"><div class="panel-head"><h2>Event markers</h2>${s?`<span id="event-count">${tag(s.events.length)}</span>`:''}</div><div class="panel-body" id="serial-events" data-count="${s?.events.length||0}">${s?.events.length?s.events.slice(-30).map(e=>`<div class="info-line"><div class="item-icon">${icon('clock')}</div><div class="body"><strong>${esc(e.text)}</strong><p>${date(e.t)}</p></div></div>`).join(''):empty('Mark a meaningful moment','Record power-on, setup changes, or anything that explains the trace.')}<p class="muted smalltext">Showing the latest 30 events; exports retain all events.</p></div></section><div class="notice"><strong>Capture capability</strong><p class="spaced">${'serial'in navigator&&isSecureContext?'Web Serial is available. Choose a compatible adapter and verify pinout and logic levels before connecting.':'Live Web Serial is unavailable in this browser or context. Settings, capture imports, analysis and exports remain available.'}</p><p class="spaced">RX preserves received bytes. TX records distinguish browser-accepted writes from uncertain attempts; neither proves device acknowledgment. Hiding local echo changes only the view.</p><p class="spaced">4 MiB / 10,000 records per capture; 16 MiB captured bytes per project. Local saves are scheduled during traffic. Keep this tab open; abrupt shutdown can lose bytes since the last save.</p><p class="spaced">v${VERSION}: release candidate awaiting physical adapter validation.</p></div></div>`;
}
function updateTerminal(){
 const el=$('#terminal');if(!el||previewReport||screen!=='boottrace')return;const s=currentSession();
 let rows=viewHex?(s?.lines||[]):sessionRows(s);const q=query.toLowerCase();
 rows=rows.filter(l=>(showTx||l.dir!=='TX')&&(directionFilter==='all'||l.dir===directionFilter)&&(!q||l.text.toLowerCase().includes(q)||(l.hex||'').replace(/\s/g,'').toLowerCase().includes(q.replace(/\s/g,''))));
 const oldScroll=el.scrollTop;
 el.innerHTML=rows.length?rows.slice(-1000).map(l=>`<div class="${l.dir==='TX'?'tx':''}"><span class="time">${esc(new Date(l.t).toLocaleTimeString())} ${esc(l.dir)}${l.dir==='TX'?' '+esc(l.status||'legacy'):''} </span>${esc(visibleText((viewHex?((l.hex||'').replace(/\s/g,'').match(/.{1,2}/g)||[]).join(' '):l.text).slice(0,4096)))}${(viewHex?(l.hex||'').length*1.5:l.text.length)>4096?' … [display clipped]':''}</div>`).join(''):`<span class="time">${s?'No matching output.':'Connect an adapter or import a session.\nExact capture bytes and event markers stay in this project.'}</span>`;
 if(followOutput&&!query)el.scrollTop=el.scrollHeight;else el.scrollTop=oldScroll;
 const events=$('#serial-events');if(events&&s&&events.dataset.count!==String(s.events.length)){events.dataset.count=String(s.events.length);events.innerHTML=s.events.slice(-30).map(e=>`<div class="info-line"><div class="body"><strong>${esc(e.text)}</strong><p>${date(e.t)}</p></div></div>`).join('')+'<p class="muted smalltext">Latest 30 events; exports retain all events.</p>';const count=$('#event-count');if(count)count.innerHTML=tag(s.events.length);}
 const stats=captureStats(s);const info=$('#serial-stats');if(info)info.innerHTML=s?.captureFormat===CAPTURE_FORMAT?`<span>RX <strong>${stats.rx.toLocaleString()} B</strong></span><span>TX written <strong>${stats.tx.toLocaleString()} B</strong></span><span>TX uncertain <strong>${stats.uncertain.toLocaleString()} B</strong></span><span>TX pending <strong>${stats.pending.toLocaleString()} B</strong></span>${s.dataLoss?'<strong class="capture-warning">Capture gap / uncertain result recorded</strong>':''}<span>Latest 1,000 matches · 4,096 displayed characters per row</span>`:'Text/legacy session · original file retained in evidence · no byte-accurate RX/TX export';
 if(serial){const c=document.querySelector(`[data-session-count="${serial.session.id}"]`);if(c)c.textContent=serial.session.lines.length;}
 const input=$('#log-search');if(input)input.oninput=()=>{query=input.value;updateTerminal()};
 $('#serial-direction').onchange=e=>{directionFilter=e.target.value;updateTerminal()};
 $('#show-tx').onchange=e=>{showTx=e.target.checked;updateTerminal()};$('#follow-output').onchange=e=>{followOutput=e.target.checked;updateTerminal()};
 el.onscroll=()=>{if(el.scrollHeight-el.scrollTop-el.clientHeight>80&&followOutput){followOutput=false;$('#follow-output').checked=false;}};
 $('#serial-send').onsubmit=sendSerial;
 $('#serial-command').oninput=e=>{serialDraft.value=e.target.value;updateSendPreview()};
 $('#send-mode').onchange=e=>{serialDraft.mode=e.target.value;render()};$('#send-ending').onchange=e=>{serialDraft.ending=e.target.value;updateSendPreview()};updateSendPreview();
}
function updateSendPreview(){const p=$('#send-preview');if(!p)return;let valid=false;try{const bytes=encodeSend(serialDraft.value,serialDraft.mode,serialDraft.ending);p.textContent=`${bytes.length} byte${bytes.length===1?'':'s'} → ${toHex(bytes.slice(0,48)).match(/../g).join(' ')}${bytes.length>48?' …':''}`;p.classList.remove('invalid');valid=true;}catch(e){p.textContent=e.message;p.classList.add('invalid');}const b=$('#send-button');if(b)b.disabled=!valid||!serial||serial.state!=='connected'||serial.stopReason||serial.session.id!==selectedSession||!!serial.pendingWrite;}
function captureChanged(){captureDirty=true;saveRevision++;if(!saveState.startsWith('Save failed'))saveState='Unsaved capture…';updateSave();if(!terminalTimer)terminalTimer=setTimeout(()=>{terminalTimer=null;updateTerminal()},100);scheduleCaptureSave();}
function scheduleCaptureSave(){if(captureSaveTimer||captureSaving)return;captureSaveTimer=setTimeout(async()=>{captureSaveTimer=null;captureDirty=false;captureSaving=true;await save();captureSaving=false;if(captureDirty)scheduleCaptureSave();},750);}
function firmView(){return heading('03 / FIRMGLASS','Look inside the artifact.','Inspect bytes, review candidates and compare evidence.',button('Inspect firmware','firmware','primary','plus'))+context()+firmwareUI.view()+advisoryUI.view();}
function networkView(){return heading('04 / NETWORK','See what the device exposes.','Connect service observations to the device, environment, and evidence.',button('Add observation','service','','plus')+button('Import Nmap XML','nmap','','upload'))+context()+`${scans.view()}<section class="panel spaced"><div class="panel-head"><h2>Service inventory</h2>${tag(count('services')+' OBSERVATIONS')}</div><div class="toolbar"><input id="service-search" type="search" placeholder="Filter host, service, port or version…" aria-label="Filter services">${button('View evidence','evidence','small','file')}</div><div class="table-wrap"><table><thead><tr><th>Host / port</th><th>Service</th><th>State</th><th>Version / product</th><th></th></tr></thead><tbody id="service-rows">${serviceRows(list('services'))}</tbody></table></div>${count('services')?'':empty('No service observations yet','Import a scoped Nmap XML scan or record an observation manually. Port numbers alone do not establish encryption or authentication.')}</section><div class="two-col spaced"><section class="panel"><div class="panel-head"><h2>Record the vantage point</h2></div><div class="panel-body"><p class="scope-text">${esc(project.scope||'Add the network vantage point, access level and device state to the assessment scope.')}</p>${button('Edit scope','scope','small spaced','edit')}</div></section><section class="panel"><div class="panel-head"><h2>From exposure to assessment</h2></div><div class="panel-body"><p class="muted smalltext" style="line-height:1.8">Review necessity, access controls and behavior in context. Scan imports update matching host/protocol/port records and preserve other observations; absence from a later scan does not prove a service is closed.</p><div class="row spaced">${button('Network test procedures','network-tests','small','assessment')}${button('Create finding','finding','small','plus')}</div></div></section></div>`}
function serviceRows(services){return services.map(s=>`<tr><td class="mono"><strong>${esc(s.host)}</strong><span class="sub">${esc(s.protocol)}/${esc(s.port)}</span></td><td>${esc(s.name||'Unknown')}${s.method?`<span class="sub">${esc(s.method==='probed'?'Probed identity':s.method==='table'?'Port-table guess':s.method==='aggregate'?'Aggregate port state':s.method)}</span>`:''}</td><td>${tag(s.state||'Observed')}</td><td>${esc(s.version||'Not identified')}</td><td><div class="row">${s.evidenceId?button('Evidence','evidence-detail','small ghost','',`data-id="${s.evidenceId}"`):''}${button('Edit','service','small','',`data-id="${s.id}"`)}</div></td></tr>`).join('')}
let assessmentTab='findings';
function assessmentView(){const tested=list('tests').filter(t=>t.status!=='Not tested').length;return heading('05 / ASSESSMENT','Make the evidence count.','Track coverage, explain findings, and verify remediation.',button('Baseline','baseline','','clock')+button('Create finding','finding','primary','plus'))+context()+`<div class="contextbar"><div class="stats-inline"><span><strong>${count('findings')}</strong> findings</span><span><strong>${list('findings').filter(x=>x.status==='Resolved').length}</strong> resolved</span><span><strong>${tested}/${TESTS.length}</strong> procedures reviewed</span></div><div class="progress" style="width:130px;margin-left:auto" aria-label="${tested} of ${TESTS.length} procedures reviewed"><span style="width:${tested/TESTS.length*100}%"></span></div></div><section class="panel"><div class="tabs">${[['findings','Findings'],['tests','Test procedures'],['compare','Baseline & retest'],['evidence','Evidence'],['investigation','Investigation'],['qualification','Qualification']].map(([id,label])=>button(label,'assessment-tab',assessmentTab===id?'active':'','',`data-id="${id}"`)).join('')}</div>${assessmentTab==='findings'?findingsView():assessmentTab==='tests'?testsView():assessmentTab==='compare'?compareView():assessmentTab==='investigation'?investigationUI.view():assessmentTab==='qualification'?qualificationUI.view():`<div class="panel-body"><div class="row between"><p class="muted smalltext">Originals, provenance and linked observations.</p><div class="row">${button('Add note','evidence-note','small','plus')}${button('Import file','evidence-file','small','upload')}</div></div>${evidenceRows(list('evidence'))}</div>`}</section>`}
function findingsView(){return list('findings').map(f=>`<article class="finding"><div class="row between"><div class="row">${tag(f.severity)}${tag(f.status)}</div>${button('Edit finding','finding','small','edit',`data-id="${f.id}"`)}</div><h3>${esc(f.title)}</h3><p>${esc(f.observation)}</p><div class="meta">${esc(f.component||'Device-level finding')} · ${esc(f.confidence)} confidence · ${f.evidenceIds.length} evidence items</div></article>`).join('')||empty('A conclusion needs a trail','Create a finding, explain its impact, and attach the observations that support it.',button('Create finding','finding','primary','plus'))}
function testsView(){return `<div class="panel-body"><p class="notice">These starter procedures support an assessment; completion is not certification. Record conditions and limitations. <a href="https://owasp.org/owasp-istg/" target="_blank" rel="noopener">OWASP IoT Security Testing Guide ↗</a></p><div class="test-grid spaced">${TESTS.map(t=>{const run=list('tests').find(x=>x.testId===t.id);return `<button class="test-card" data-action="test" data-id="${t.id}"><div><span class="eyebrow">${t.area}</span><h3>${t.title}</h3><p>${t.why}</p><div class="spaced">${tag(run?.status||'Not tested')}</div></div>${icon('arrow')}</button>`}).join('')}</div></div>`}
function compareView(){const bs=project.baselines.filter(x=>x.deviceId===project.deviceId);if(!bs.some(x=>x.id===selectedBaseline))selectedBaseline=bs[bs.length-1]?.id||'';const b=bs.find(x=>x.id===selectedBaseline);let changes=[];if(b)changes=compareSnapshots(b.snapshot,snapshot(project));return `<div class="panel-body"><div class="row between wrap"><div><h3>Baseline → current state</h3><p class="muted smalltext spaced">Comparisons are observations, not automatic verdicts.</p></div>${bs.length?`<select id="baseline-select" aria-label="Selected baseline">${bs.map(x=>`<option value="${x.id}" ${x.id===selectedBaseline?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`:''}</div>${b?`<div class="baseline-row spaced"><p><strong>${esc(b.label)}</strong> · ${date(b.createdAt)}</p><p class="muted">${esc(b.conditions||'No conditions recorded.')}</p></div><p class="notice spaced">Compare like-for-like device configurations, access levels and collection methods. Service absence and changed firmware hashes do not prove remediation.</p>${changes.length?`<div class="table-wrap spaced"><table><thead><tr><th>Change</th><th>Area</th><th>Item / detail</th></tr></thead><tbody>${changes.map(c=>`<tr><td>${tag(c.change,c.change==='Removed'?'warn':'')}</td><td>${esc(c.group)}</td><td><strong>${esc(c.label)}</strong><span class="sub">${esc(c.detail)}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No recorded differences','The tracked device details, interfaces, service inventory, firmware records, findings and test statuses match this baseline.')}`:empty('Freeze a meaningful state','Save the current observations before an update or retest. Evidence originals stay in the project.',button('Create baseline','baseline','primary','clock'))}</div>`}
function wireViews(){advisoryUI.wire();debuggerUI.wire();firmwareUI.wire();const board=$('#board-map');if(board)board.onclick=e=>{if(!placing||e.target.closest('button'))return;const x=list('interfaces').find(x=>x.id===selectedInterface);if(!x)return;const r=board.getBoundingClientRect();x.x=Math.round((e.clientX-r.left)/r.width*1000)/10;x.y=Math.round((e.clientY-r.top)/r.height*1000)/10;placing=false;changed('Marker position saved.');};if($('#artifact-select'))$('#artifact-select').onchange=e=>{selectedArtifact=e.target.value;render();wireViews()};if($('#string-search'))$('#string-search').oninput=e=>{const a=list('artifacts').find(x=>x.id===selectedArtifact);const matches=a.strings.filter(s=>s.toLowerCase().includes(e.target.value.toLowerCase()));$('#strings').textContent=matches.slice(0,150).join('\n')||'No matching strings.'};if($('#service-search'))$('#service-search').oninput=e=>{$('#service-rows').innerHTML=serviceRows(list('services').filter(s=>[s.host,s.port,s.name,s.version,s.protocol].join(' ').toLowerCase().includes(e.target.value.toLowerCase())))};if($('#baseline-select'))$('#baseline-select').onchange=e=>{selectedBaseline=e.target.value;render();wireViews()};}
const basicRender=render;render=()=>{basicRender();wireViews()};
function projectDialog(){showDialog('Assessment project',`<div class="stack"><p class="help-copy">${project?`<strong>${esc(project.title)}</strong><br>${project.devices.length} devices · ${project.evidence.length} evidence items · updated ${date(project.updatedAt)}`:'Create a new project or open a portable JSON export.'}</p>${project?`<div class="row wrap">${button('Export project JSON','export','','download')}${button('Edit title & scope','scope','','edit')}${button('Add device','new-device','','plus')}</div>`:''}<div class="row wrap">${button('New assessment','new','','plus')}${button('Import project','import-project','','upload')}${button('Load sample','sample','','file')}</div><p class="notice">One assessment is active on this browser. Export before switching projects. JSON exports include original evidence; reports omit original files.</p></div>`)}
function newDialog(){showDialog('New assessment',`<div class="form-grid">${field('Assessment title','title','','text',true)}${field('First device name','name','Device under test','text',true)}${area('Scope, environment & access level','scope','')}</div>${project?'<p class="notice spaced">This replaces the active workspace. Export the current project first if you want to keep it.</p>':''}`,data=>{if(serial)throw Error('Disconnect serial before switching projects.');project=newProject(data.get('title').trim(),data.get('name').trim(),data.get('scope'));selectedInterface=selectedSession=selectedArtifact=selectedBaseline='';screen='boundary';changed('Clean assessment created.');},'Create assessment',project?button('Export current','export','small','download'):'')}
function deviceDialog(add=false){const d=add?{}:device();showDialog(add?'Add device':'Device passport',`<div class="form-grid">${field('Device name','name',d.name||'')}${field('Model / product','model',d.model||'')}${field('Hardware revision','hw',d.hw||'')}${field('Firmware version','firmware',d.firmware||'')}${area('Device notes','notes',d.notes||'')}</div>`,data=>{if(serial&&add)throw Error('Disconnect serial before changing devices.');const values=Object.fromEntries(data);if(add){const n={...values,id:uid('dev'),photo:''};project.devices.push(n);project.deviceId=n.id;selectedInterface=selectedSession=selectedArtifact=selectedBaseline=''}else Object.assign(d,values);changed(add?'Device added.':'Device details saved.')})}
function interfaceDialog(id=''){const x=project.interfaces.find(x=>x.id===id)||{x:50,y:50,type:'UART',status:'Suspected'};showDialog(id?'Edit interface':'Add interface',`<div class="form-grid">${field('Interface label','label',x.label||'')}${selectField('Interface type','type',['UART','JTAG','SWD','SPI','I²C','USB','Ethernet','Wi-Fi','Bluetooth','Radio','Memory','Processor','Other'],x.type)}${selectField('Identification','status',['Suspected','Observed','Verified'],x.status)}${field('Measured logic level','voltage',x.voltage||'')}${field('Pin assignment','pins',x.pins||'','text',true)}${field('Marker X · % from left','x',x.x,'number')}${field('Marker Y · % from top','y',x.y,'number')}${area('Observations / uncertainty','notes',x.notes||'')}<div class="field full">Linked evidence${evidenceChecks(x.evidenceIds)}</div></div>`,data=>{const v=Object.fromEntries(data);v.x=Number(v.x);v.y=Number(v.y);if(!Number.isFinite(v.x)||!Number.isFinite(v.y)||v.x<0||v.x>100||v.y<0||v.y>100)throw Error('Marker coordinates must be between 0 and 100.');v.evidenceIds=data.getAll('evidenceIds');if(id)Object.assign(x,v);else{Object.assign(x,v,{id:uid('if'),deviceId:project.deviceId});project.interfaces.push(x)}selectedInterface=x.id;changed('Interface saved.');},'Save interface',id?button('Remove','remove-interface','small danger','',`data-id="${id}"`):'')}
function connectionDialog(id=''){const x=project.connections.find(x=>x.id===id)||{};showDialog(id?'Edit connection':'Add system connection',`<div class="form-grid">${field('From','from',x.from||device().name)}${field('To','to',x.to||'')}${field('Protocol / transport','protocol',x.protocol||'')}${field('Trust boundary','boundary',x.boundary||'')}${area('Notes','notes',x.notes||'')}</div>`,data=>{const v=Object.fromEntries(data);if(!v.from.trim()||!v.to.trim())throw Error('Record both ends of this connection.');if(id)Object.assign(x,v);else project.connections.push({...v,id:uid('link'),deviceId:project.deviceId});changed('Connection saved.')},'Save',id?button('Remove','remove-connection','small danger','',`data-id="${id}"`):'')}
function evidenceDialog(){showDialog('Evidence register',`<div class="row wrap">${button('Record observation','evidence-note','primary','plus')}${button('Import file','evidence-file','','upload')}</div><div class="spaced">${evidenceRows(list('evidence'))}</div><p class="notice spaced">Original artifacts remain local. SHA-256 identifies the recorded bytes; it does not establish who produced them. Record source, tool and acquisition conditions.</p>`)}
function evidenceNote(){showDialog('Record an observation',`<div class="form-grid">${field('Evidence title','title','','text',true)}${area('Observation text','text','')}${field('Source / location','source',selectedInterface?project.interfaces.find(x=>x.id===selectedInterface)?.label||'':'')}${field('Tool & version','tool','Manual observation')}${area('Acquisition conditions','conditions','')}${area('Interpretation / limitations','notes','')}</div>`,async data=>{if(!data.get('text').trim())throw Error('Enter the observation to preserve.');const e=await textEvidence(data.get('title'),data.get('text'),'Observation',{source:data.get('source'),tool:data.get('tool'),conditions:data.get('conditions'),notes:data.get('notes')});const iface=list('interfaces').find(x=>x.id===selectedInterface);if(iface){iface.evidenceIds||=[];iface.evidenceIds.push(e.id)}changed('Observation preserved as evidence.')},'Save evidence')}
function evidenceDetail(id){const e=project.evidence.find(x=>x.id===id);if(!e){notify('This evidence reference is not available.');return}const text=/^text\/|json|xml/.test(e.mime)||['Observation','Serial log','Network scan'].includes(e.kind)?rawText(e).slice(0,16000):'';showDialog('Evidence details',`<div class="row between">${tag(e.kind)}<span class="muted smalltext">${date(e.createdAt)} · ${(e.size||0).toLocaleString()} bytes</span></div><h3 class="spaced">${esc(e.title)}</h3><p class="hash spaced">SHA-256 ${esc(e.hash||'Not available')}</p>${text?`<details class="spaced"><summary>View original excerpt (may contain sensitive values)</summary><pre class="code-preview">${esc(text)}</pre></details>`:''}<div class="form-grid spaced">${field('Source','source',e.source||'')}${field('Tool & version','tool',e.tool||'')}${area('Acquisition conditions','conditions',e.conditions||'')}${area('Interpretation / limitations','notes',e.notes||'')}</div><div class="row spaced">${button('Download original','evidence-download','','download',`data-id="${id}"`)}${button('Create finding','finding-from-evidence','','plus',`data-id="${id}"`)}</div>`,data=>{Object.assign(e,Object.fromEntries(data));changed('Evidence metadata saved.')})}
function findingDialog(id='',evidenceId=''){const f=project.findings.find(x=>x.id===id)||{severity:'Medium',confidence:'Medium',status:'Open',evidenceIds:Array.isArray(evidenceId)?evidenceId:evidenceId?[evidenceId]:[]};showDialog(id?'Edit finding':'Create finding',`<div class="form-grid">${field('Finding title','title',f.title||'','text',true)}${field('Affected component / interface','component',f.component||'','text',true)}${selectField('Severity','severity',['Informational','Low','Medium','High','Critical'],f.severity)}${selectField('Confidence','confidence',['Low','Medium','High'],f.confidence)}${selectField('Review status','status',['Candidate','Open','In remediation','Resolved','Accepted risk','Not reproducible'],f.status,true)}${area('Observed behavior','observation',f.observation||'')}${area('Impact and prerequisites','impact',f.impact||'')}${area('Reproduction procedure','reproduction',f.reproduction||'')}${area('Recommended remediation','remediation',f.remediation||'')}${area('Retest criteria / result','retest',f.retest||'')}<div class="field full">Supporting evidence${evidenceChecks(f.evidenceIds)}</div></div>`,data=>{const v={...Object.fromEntries(data),evidenceIds:data.getAll('evidenceIds')};if(!v.observation.trim())throw Error('Describe the observed behavior.');if(v.status==='Resolved'&&(!v.retest.trim()||!v.evidenceIds.length))throw Error('A resolved finding needs a retest record and linked evidence.');if(id)Object.assign(f,v);else project.findings.push({...v,id:uid('finding'),deviceId:project.deviceId,createdAt:now()});changed('Finding saved.')},'Save finding',id?button('Delete','delete-finding','small danger','',`data-id="${id}"`):'')}
function testDialog(id){const t=TESTS.find(x=>x.id===id);if(!t)return;const run=list('tests').find(x=>x.testId===id)||{status:'Not tested',notes:'',evidenceIds:[]};showDialog(t.title,`<div class="help-copy"><p><strong>Purpose</strong><br>${t.why}</p><p><strong>Procedure</strong><br>${t.steps}</p><p><strong>Expected result</strong><br>${t.expected}</p></div><div class="form-grid">${selectField('Recorded result','status',['Not tested','Passed','Failed','Inconclusive','Not applicable'],run.status,true)}${area('Actual result, conditions & limitations','notes',run.notes)}<div class="field full">Supporting evidence${evidenceChecks(run.evidenceIds)}</div></div>`,data=>{const v={status:data.get('status'),notes:data.get('notes'),evidenceIds:data.getAll('evidenceIds')};if(v.status!=='Not tested'&&!v.notes.trim())throw Error('Record the actual result or the reason the test is not applicable.');if(run.id)Object.assign(run,v);else project.tests.push({...v,id:uid('test'),deviceId:project.deviceId,testId:id});changed('Test result recorded.')},'Save result')}
function assumptionsDialog(){showDialog('Assumptions register',`<p class="notice">Keep assumptions separate from measured evidence and verified findings.</p>${list('assumptions').map(a=>`<div class="info-line"><div class="body"><strong>${esc(a.text)}</strong><p>${esc(a.status)} · ${esc(a.basis)}</p></div>${button('Edit','assumption','small','',`data-id="${a.id}"`)}</div>`).join('')}<div class="spaced">${button('Add assumption','assumption','primary','plus')}</div>`)}
function assumptionDialog(id=''){const a=project.assumptions.find(x=>x.id===id)||{status:'Unverified'};showDialog('Record an assumption',`<div class="form-grid">${area('Assumption','text',a.text||'')}${selectField('State','status',['Unverified','Supported','Rejected'],a.status,true)}${area('Basis / verification needed','basis',a.basis||'')}</div>`,data=>{const v=Object.fromEntries(data);if(!v.text.trim())throw Error('Enter the assumption.');if(id)Object.assign(a,v);else project.assumptions.push({...v,id:uid('assumption'),deviceId:project.deviceId});changed('Assumption saved.')})}
function serviceDialog(id=''){const s=project.services.find(x=>x.id===id)||{protocol:'tcp',state:'Observed'};showDialog(id?'Edit service observation':'Add service observation',`<div class="form-grid">${field('Host / address','host',s.host||'')}${field('Port','port',s.port||'','number')}${selectField('Transport','protocol',['tcp','udp','other'],s.protocol)}${selectField('Observed state','state',['Observed','open','closed','filtered','open|filtered','unknown'],s.state)}${field('Service name','name',s.name||'')}${field('Product / version','version',s.version||'')}<label class="field full">Evidence source<select name="evidenceId"><option value="">No evidence linked</option>${list('evidence').map(e=>`<option value="${e.id}" ${s.evidenceId===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label></div>`,data=>{const v=Object.fromEntries(data);v.port=Number(v.port);if(!v.host.trim()||!Number.isInteger(v.port)||v.port<0||v.port>65535)throw Error('Enter a host and port from 0 through 65535.');if(id)Object.assign(s,v);else{if(list('services').some(x=>x.host===v.host&&x.port===v.port&&x.protocol===v.protocol))throw Error('This service already exists; edit its observation.');project.services.push({...v,id:uid('svc'),deviceId:project.deviceId})}changed('Service observation saved.')},'Save',id?button('Remove observation','remove-service','small danger','',`data-id="${id}"`):'')}
function baselineDialog(){showDialog('Freeze assessment baseline',`<div class="form-grid">${field('Baseline label','label',`Firmware ${device().firmware||'unknown'} · ${new Date().toLocaleDateString()}`,'text',true)}${area('Device configuration, access level & collection conditions','conditions','')}</div><p class="notice spaced">This freezes tracked device details, interfaces, services, firmware fingerprints, test statuses and finding states. Existing evidence remains in the project.</p>`,data=>{const b={id:uid('base'),deviceId:project.deviceId,label:data.get('label'),conditions:data.get('conditions'),createdAt:now(),snapshot:snapshot(project)};project.baselines.push(b);selectedBaseline=b.id;assessmentTab='compare';screen='assessment';changed('Baseline frozen.')},'Save baseline')}
async function importLog(file){if(file.size>32*1024*1024)throw Error('Use a log under 16 MiB.');const text=await file.text();if(!text.trim())throw Error('The log is empty.');const lines=text.split(/\r?\n/);if(lines.length>10000)throw Error('Use a log with 10,000 lines or fewer.');const e=await evidenceFromFile(file,'Serial log');project.evidence.push(e);const s={id:uid('session'),deviceId:project.deviceId,label:file.name,createdAt:now(),evidenceId:e.id,lines:lines.map(text=>({t:now(),dir:'IMPORT',text,hex:[...new TextEncoder().encode(text)].map(b=>b.toString(16).padStart(2,'0')).join(' ')})),events:[{t:now(),text:'Imported text log. Display timestamps indicate import time; embedded source timestamps are unchanged.'}]};project.sessions.push(s);selectedSession=s.id;screen='boottrace';changed('Log imported. Original timestamps remain in its text.')}
async function importFirmware(file){screen='firmglass';await firmwareUI.inspect(file)}
async function importSbom(file){const p=project,deviceId=p.deviceId;if(file.size>1024*1024)throw Error('Use SBOM JSON of 1 MiB or less.');const obj=strictJSON(await file.text()),components=parseSbom(obj);if(components.length>10000||p.components.length+components.length>20000)throw Error('Use at most 10,000 components per SBOM and 20,000 per project.');const e=await evidenceFromFile(file,'SBOM');if(project!==p||p.deviceId!==deviceId)throw Error('Project/device changed.');if(p.evidence.some(x=>x.kind==='SBOM'&&x.deviceId===deviceId&&x.hash===e.hash))throw Error('This SBOM original is already imported.');const additions=components.map(c=>({...c,id:uid('component'),deviceId,evidenceId:e.id}));validateProject({...p,evidence:[...p.evidence,e],components:[...p.components,...additions]});p.evidence.push(e);p.components.push(...additions);screen='firmglass';changed(`${components.length} components imported; original declarations preserved.`)}
async function importNmap(file){if(file.size>32*1024*1024)throw Error('Use XML of 16 MiB or less.');const parsed=parseNmap(await file.text());const e=await evidenceFromFile(file,'Network scan');e.tool=parsed.tool;e.conditions=parsed.args||'Scan arguments not present; record the vantage point.';project.evidence.push(e);project.services=mergeServices(project.services,parsed.observations,project.deviceId,e.id);screen='network';changed(`${parsed.observations.length} explicit service observations imported. Original XML preserved.`)}
function connectionFields(options){return `<div class="form-grid">${field('Baud rate','baudRate',options.baudRate,'number')}${selectField('Data bits','dataBits',['7','8'],String(options.dataBits))}${selectField('Parity','parity',['none','even','odd'],options.parity)}${selectField('Stop bits','stopBits',['1','2'],String(options.stopBits))}${selectField('Flow control','flowControl',['none','hardware'],options.flowControl)}${field('Buffer size (bytes)','bufferSize',options.bufferSize,'number')}</div>`}
function profileDialog(){showDialog('Serial connection settings',connectionFields(device().serialProfile||DEFAULT_SERIAL)+`<p class="notice spaced">Saved per device. Hardware flow control requires compatible wiring. Connection settings do not identify pinout or electrical levels.</p>`,data=>{device().serialProfile=serialOptions(Object.fromEntries(data));changed('Serial settings saved for this device.')},'Save settings')}
function connectDialog(){
 if(serial){notify('Disconnect the current adapter before starting another session.');return;}
 const available='serial'in navigator&&isSecureContext;
 if(!available){showDialog('Serial connection unavailable',`<p class="notice">Web Serial is unavailable in this context. Live capture requires a supported browser on HTTPS or localhost. Imported captures and all local analysis remain available.</p><div class="row wrap spaced">${button('Connection settings','serial-profile','','settings')}${button('Import session','import-session','','upload')}</div>`);return;}
 showDialog('Connect a serial adapter',field('Session label','label',`Capture · ${device().name}`,'text',true)+connectionFields(device().serialProfile||DEFAULT_SERIAL)+`<p class="notice spaced">${available?'Capture starts when the chosen port opens. Opening an adapter may change control lines or reset a target; verify wiring and the target’s behavior first.':'Web Serial is unavailable in this context. Use a supported browser on HTTPS or localhost. You can still save connection settings and import captures.'}</p>`,available?async data=>{
  const options=serialOptions(Object.fromEntries(data));const used=project.sessions.reduce((n,s)=>n+captureStats(s).total,0);if(used>=16*1024*1024)throw Error('The project has reached its 16 MiB serial-capture limit. Export it and start another assessment.');
  const port=await navigator.serial.requestPort();
  const s=createCapture({id:uid('session'),deviceId:project.deviceId,label:data.get('label').trim()||`Capture · ${device().name}`,options,context:{deviceName:device().name,firmware:device().firmware,hardware:device().hw}});
  const active=new SerialConnection(port,s,{limits:{...CAPTURE_LIMITS,bytes:Math.min(CAPTURE_LIMITS.bytes,16*1024*1024-used)},onChange:()=>{if(project.sessions.includes(s))captureChanged()},onState:state=>{if(state==='stopping'&&serial===active){save();render()}}});
  serial=active;try{await active.open()}catch(e){serial=null;throw Error('Could not open the adapter: '+e.message)}
  project.sessions.push(s);device().serialProfile=options;selectedSession=s.id;serialDraft.value='';screen='boottrace';previewReport=false;query='';followOutput=true;changed('Serial connected. No command was sent.');
  active.start().then(async()=>{clearTimeout(captureSaveTimer);captureSaveTimer=null;captureDirty=false;if(serial===active)serial=null;await save();render();notify(`Serial ${s.status}. Session preserved; reconnect starts a new capture.`);}).catch(err=>notify('Capture cleanup failed: '+err.message));
 } : null,'Choose adapter');
}
async function disconnectSerial(){if(!serial)return;await serial.stop();}
async function sendSerial(event){event.preventDefault();const active=serial;if(!active||active.session.id!==selectedSession)return;const draft={...serialDraft};let bytes;try{bytes=encodeSend(draft.value,draft.mode,draft.ending);const work=active.send(bytes);updateSendPreview();await work;const d=project.devices.find(x=>x.id===active.session.deviceId);d.serialHistory=[draft,...(d.serialHistory||[]).filter(h=>h.value!==draft.value||h.mode!==draft.mode||h.ending!==draft.ending)].slice(0,20);if(serialDraft.value===draft.value)serialDraft.value='';save();if(screen==='boottrace')render();}catch(e){notify('Send failed or incomplete: '+e.message);updateSendPreview();}}
function historyDialog(){const history=device().serialHistory||[];showDialog('Command history',`<p class="notice">Saved with this project. Choosing an entry only fills the composer; it never sends automatically.</p><div class="stack spaced">${history.map((h,i)=>`<div class="row"><code class="history-value">${esc(h.value||'(line ending only)')}</code><span class="smalltext">${esc(h.mode)} / ${h.mode==='hex'?'exact bytes':esc(h.ending)}</span>${button('Load draft','history-load','small','','data-id="'+i+'"')}</div>`).join('')}</div>`)}
async function captureEnvelope(s){const snapshot=structuredClone(s);for(const line of snapshot.lines)delete line.text;return {app:'PROBE serial capture',format:CAPTURE_FORMAT,version:VERSION,exportedAt:now(),session:snapshot,sha256:{rx:await sha256(rawCapture(snapshot,'RX')),txWritten:await sha256(rawCapture(snapshot,'TX'))}}}
function sessionExportDialog(){const s=currentSession();if(!s)return;showDialog('Export serial session',`<p class="help-copy">${esc(s.label)} · original records and settings remain in the project.</p><div class="stack spaced">${button('Readable transcript (.log)','session-transcript','','file')}${s.captureFormat===CAPTURE_FORMAT?button('Capture records + hashes (.json)','capture-download','primary','download')+button('Received bytes (.rx.bin)','capture-rx','','download')+button('Browser-accepted TX bytes (.tx.bin)','capture-tx','','download'):'<p class="notice">This legacy/text session has no byte-accurate RX/TX export. Its original file remains in evidence.</p>'}</div><p class="notice spaced">Raw RX concatenates received bytes. Raw TX includes successful browser writes only, not pending or uncertain attempts. The capture JSON preserves attempt statuses, record times, gaps and events. These are observation timestamps, not wire timing. If your browser blocks a binary download, the capture JSON retains the same bytes.</p>`)}
async function importCapture(file){
 if(serial)throw Error('Disconnect before importing a capture.');if(file.size>32*1024*1024)throw Error('Capture JSON must be under 16 MiB.');const payload=JSON.parse(await file.text());
 if(payload.app!=='PROBE serial capture'||payload.format!==CAPTURE_FORMAT)throw Error('Choose an exported PROBE serial capture JSON.');
 const s=validateCapture(payload.session);if(await sha256(rawCapture(s,'RX'))!==payload.sha256?.rx||await sha256(rawCapture(s,'TX'))!==payload.sha256?.txWritten)throw Error('Capture byte hashes do not match.');
 if(project.sessions.reduce((n,x)=>n+captureStats(x).total,0)+captureStats(s).total>16*1024*1024)throw Error('This import would exceed the project’s 16 MiB capture limit.');
 const e=await evidenceFromFile(file,'Serial capture');project.evidence.push(e);s.originSessionId=s.id;s.id=uid('session');s.deviceId=project.deviceId;s.evidenceId=e.id;s.importedAt=now();recoverCapture(s,'Imported a live capture snapshot. It is no longer connected; pending writes have an uncertain result.');project.sessions.push(s);selectedSession=s.id;screen='boottrace';previewReport=false;query='';changed('Serial capture imported and RX/TX hashes verified.');
}
async function saveSessionEvidence(){const s=currentSession();if(!s)return;let e;if(s.captureFormat===CAPTURE_FORMAT){const snapshot=await captureEnvelope(s);e=await evidenceFromFile(new File([JSON.stringify(snapshot,null,2)],safeName(s.label)+'.serial.json',{type:'application/json'}),'Serial capture');Object.assign(e,{source:device().name,tool:`PROBE ${VERSION}`,conditions:optionsLabel(s.options),notes:'Snapshot includes raw RX/TX records, write outcomes, events and byte hashes.'});project.evidence.push(e);}else e=await textEvidence(s.label+' · capture snapshot',transcript(s),'Serial log',{source:device().name,tool:`PROBE ${VERSION}`,conditions:`Session ${s.id}; capture created ${s.createdAt}`});s.evidenceId=e.id;const iface=list('interfaces').find(x=>x.id===selectedInterface);if(iface){iface.evidenceIds||=[];iface.evidenceIds.push(e.id)}changed('Session snapshot saved as evidence.');}
function eventDialog(){const s=list('sessions').find(x=>x.id===selectedSession);if(!s)return;showDialog('Bookmark this session',field('Event description','label','','text',true),data=>{s.events.push({t:now(),text:data.get('label')});changed('Event marker added.')},'Add marker')}
function compareSessions(){const sessions=list('sessions');if(sessions.length<2)return;showDialog('Compare observation sessions',`<div class="form-grid">${['Before','After'].map((label,i)=>`<label class="field">${label}<select name="${label.toLowerCase()}">${sessions.map((s,j)=>`<option value="${s.id}" ${j===i?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label>`).join('')}</div><p class="notice spaced">Compare complete received text lines across read boundaries. TX attempts are excluded. Host capture timestamps are ignored; timestamps embedded by the device remain. This is a content comparison, not timing analysis.</p>`,data=>{const a=sessions.find(s=>s.id===data.get('before')),b=sessions.find(s=>s.id===data.get('after'));if(a===b)throw Error('Choose two different sessions.');const lines=s=>new Set(sessionRows(s).filter(l=>l.dir!=='TX').flatMap(l=>l.text.split(/\r?\n/)).filter(Boolean));const A=lines(a),B=lines(b),removed=[...A].filter(x=>!B.has(x)),added=[...B].filter(x=>!A.has(x));setTimeout(()=>showDialog('Session comparison',`<p class="muted smalltext">${esc(a.label)} → ${esc(b.label)}</p><div class="two-col spaced"><div><h3>Only in before · ${removed.length}</h3><pre class="code-preview">${esc(removed.slice(0,200).join('\n')||'No unique lines.')}</pre></div><div><h3>Only in after · ${added.length}</h3><pre class="code-preview">${esc(added.slice(0,200).join('\n')||'No unique lines.')}</pre></div></div><p class="notice">Up to 200 unique lines per side. Full originals remain in the sessions and evidence. Check gaps and acquisition conditions before interpreting differences.</p>`),0)},'Compare')}
function reportBody(includeExcerpts=false){const d=device();const evidence=list('evidence');return `<div class="report-meta">GREEN SHOE GARAGE / FIELD INSTRUMENTS / PROBE v${VERSION}</div><h1>${esc(project.title)}</h1><p class="report-meta">${project.sample?'FICTIONAL SAMPLE ASSESSMENT · ':''}Generated ${esc(new Date().toLocaleString())}<br>Device: ${esc(d.name)} · ${esc(d.model)} · HW ${esc(d.hw||'unknown')} · FW ${esc(d.firmware||'unknown')}</p><h2>Scope and conditions</h2><p>${esc(project.scope||'Not recorded.')}</p><p>${esc(d.notes)}</p><h2>Assessment summary</h2><p>${count('findings')} findings · ${list('findings').filter(x=>x.status==='Resolved').length} resolved · ${count('evidence')} evidence items · ${list('tests').filter(t=>t.status!=='Not tested').length} of ${TESTS.length} starter procedures reviewed.</p><p class="report-meta">Results apply to the recorded device, access level and test conditions. Untested and inconclusive areas remain explicit. This report is not a certification.</p><h2>Findings</h2>${list('findings').map((f,i)=>`<article class="report-finding"><h3>F${i+1}. ${esc(f.title)}</h3><p class="report-meta">Severity: ${esc(f.severity)} · Confidence: ${esc(f.confidence)} · Status: ${esc(f.status)}<br>Affected component: ${esc(f.component||'Not specified')}</p>${[['Observed behavior',f.observation],['Impact and prerequisites',f.impact],['Reproduction',f.reproduction],['Remediation',f.remediation],['Retest criteria / result',f.retest]].map(([k,v])=>`<p><strong>${k}</strong><br>${esc(v||'Not recorded.')}</p>`).join('')}<p><strong>Evidence</strong><br>${f.evidenceIds.map(id=>{const e=project.evidence.find(x=>x.id===id);return e?`${esc(e.title)} (${esc(e.id)})`:'Missing reference'}).join('<br>')||'No evidence linked.'}</p></article>`).join('')||'<p>No findings recorded.</p>'}<h2>Test coverage</h2><table><thead><tr><th>Procedure</th><th>Result</th><th>Actual result / limitations</th></tr></thead><tbody>${TESTS.map(t=>{const r=list('tests').find(x=>x.testId===t.id);return `<tr><td>${esc(t.title)}</td><td>${esc(r?.status||'Not tested')}</td><td>${esc(r?.notes||'—')}</td></tr>`}).join('')}</tbody></table><h2>Assumptions</h2>${list('assumptions').map(a=>`<p><strong>${esc(a.status)}:</strong> ${esc(a.text)}<br>Basis: ${esc(a.basis||'Not recorded.')}</p>`).join('')||'<p>No assumptions recorded.</p>'}<h2>Interfaces</h2><table><thead><tr><th>Interface</th><th>Identification</th><th>Pinout / level</th></tr></thead><tbody>${list('interfaces').map(i=>`<tr><td>${esc(i.label)} · ${esc(i.type)}</td><td>${esc(i.status)}</td><td>${esc(i.pins)} / ${esc(i.voltage)}</td></tr>`).join('')}</tbody></table><h2>Service observations</h2><table><thead><tr><th>Endpoint</th><th>Service / state</th><th>Product / version</th></tr></thead><tbody>${list('services').map(s=>`<tr><td>${esc(s.host)} ${esc(s.protocol)}/${esc(s.port)}</td><td>${esc(s.name)} · ${esc(s.state)}</td><td>${esc(s.version)}</td></tr>`).join('')}</tbody></table><h2>Firmware and components</h2>${list('artifacts').map(a=>`<p><strong>${esc(a.name)}</strong> · ${esc(a.kind)} · ${a.size} bytes<br><span class="hash">SHA-256 ${esc(a.hash)}</span></p>`).join('')||'<p>No firmware artifacts recorded.</p>'}<table><thead><tr><th>Component</th><th>Version</th><th>License</th></tr></thead><tbody>${list('components').map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.version)}</td><td>${esc(c.license)}</td></tr>`).join('')}</tbody></table>${advisoryUI.report()}<h2>System connections</h2>${list('connections').map(c=>`<p>${esc(c.from)} → ${esc(c.to)} · ${esc(c.protocol)}<br>Boundary: ${esc(c.boundary)}</p>`).join('')||'<p>No connections recorded.</p>'}<h2>Evidence register</h2>${evidence.map(e=>`<article class="report-finding"><h3>${esc(e.title)}</h3><p class="report-meta">${esc(e.id)} · ${esc(e.kind)} · ${esc(e.createdAt)}<br>Source: ${esc(e.source||'Unspecified')}<br>Tool: ${esc(e.tool||'Unspecified')}<br>Conditions: ${esc(e.conditions||'Unspecified')}</p><p class="hash">SHA-256: ${esc(e.hash||'Not available')}</p>${includeExcerpts&&(/^text\/|json|xml/.test(e.mime)||e.kind==='Observation')?`<pre>${esc(rawText(e).slice(0,3000))}</pre>`:''}</article>`).join('')||'<p>No evidence.</p>'}<h2>Investigation bundles</h2>${(project.investigationBundles||[]).filter(b=>b.deviceId===d.id).map(b=>`<p><strong>${esc(b.label)}</strong> · ${esc(b.createdAt)}<br>${esc(b.conditions)}<br>${b.entries.map(x=>esc(x.title)+' · SHA-256 '+esc(x.sha256)).join('<br>')}</p>`).join('')||'<p>No bundles recorded.</p>'}<h2>Baselines</h2>${project.baselines.filter(x=>x.deviceId===d.id).map(b=>`<p><strong>${esc(b.label)}</strong> · ${esc(b.createdAt)}<br>${esc(b.conditions)}</p>`).join('')||'<p>No baselines recorded.</p>'}<h2>Method and limits</h2><p>PROBE starter procedures are informed by the OWASP IoT Security Testing Guide: https://owasp.org/owasp-istg/. Procedure completion does not imply compliance. Firmware triage identifies bytes and readable strings; component vulnerability applicability requires review. Imported scans reflect their original collection conditions. Original artifact bytes are not embedded in this report.</p><p class="report-meta">Project ${esc(project.id)} · schema 1 · updated ${esc(project.updatedAt)}</p>`}
function reportDialog(){showDialog('Assessment report',`<p class="help-copy">Generate a report for <strong>${esc(device().name)}</strong>. Findings, test coverage, assumptions, provenance and baselines are included.</p><label class="row spaced"><input type="checkbox" id="report-excerpts"> Include raw text excerpts (up to 3,000 characters per item)</label><p class="notice spaced">Raw evidence excerpts are excluded by default. Review your finding text and provenance before sharing. Original files remain in the project export.</p><div class="row wrap spaced">${button('Preview report','report-preview','primary','file')}${button('Print / Save as PDF','print','','report')}</div><p class="muted smalltext spaced">Choose Save as PDF in your browser’s print destination. The document is formatted separately from the app interface.</p>`)}
function helpDialog(){showDialog('PROBE · field notes',`<div class="help-copy"><p><strong>v${VERSION} · Integrated assessment workbench</strong><br>Map → observe → test → explain → retest.</p><h3>What works here</h3><ul><li>Device passports, board photos, interface markers and connections.</li><li>Byte-preserving serial RX/TX, configurable text/hex sends, saved connection settings, capture imports/exports and complete-line comparison.</li><li>Worker-based firmware inspection, offset search, entropy regions, masked review candidates, archive extraction, byte/file comparisons and CycloneDX/SPDX import.</li><li>Local-companion Nmap acquisition, scan evidence/history/retest, XML imports and manual service observations.</li><li>OpenOCD/GDB structured controls, registers, memory, symbols, hardware breakpoints and debugger evidence snapshots via the companion.</li><li>Guided test records, qualification ledgers, findings, assumptions, clock-aware investigation context, frozen evidence bundles and reports.</li><li>Strict JSON/INI/literal .env configuration and SBOM version/license comparisons, with extracted child provenance.</li></ul><h3>Local data and recovery</h3><p>The active project, including originals, is stored in this browser using IndexedDB. Assessment data stays on this computer. Native scanning sends probes to your selected targets and stores scan originals in the local companion’s evidence directory. Export JSON for a durable backup and transfer between browsers. Clearing browser storage removes the local workspace. One project is active at a time; export before switching.</p><h3>Offline use</h3><p>The static application caches itself after a successful load over HTTPS or localhost. Open it once while online, then reload offline. Private hosted access may need an online sign-in; the portable package is the recommended offline deployment. Serial permissions and adapter support depend on the browser.</p><div class="row">${button('Check offline readiness','offline-check','small','check')}</div><h3>Current limits</h3><p>Files: 32 MiB each; evidence: 128 MiB per project. Serial sessions: 10,000 records or 4 MiB; 16 MiB captured bytes per project. Native scanning needs installed Nmap. Debugging needs OpenOCD, ARM-capable GDB and an operator-reviewed profile. Extraction supports ZIP/TAR/CPIO/gzip/bzip2/xz and a bounded SquashFS adapter (requires unsquashfs), and requires Linux bubblewrap plus Python; unavailable isolation disables extraction. No firmware execution, flash writes, MMIO access or secure-boot verification. Candidate matches are not vulnerability verdicts.</p><h3>Roadmap and release status</h3><p><strong>v1.8.0-rc.1:</strong> v1.7 adds bounded UDP opt-in, host discovery, scoped IPv6, hardware watch modes and stop configuration, plus an unverified ST-Link candidate. v1.8 adds CPIO and compressed streams, file metadata comparisons, literal .env comparison, richer component identity and dated offline OSV review. Stable release hardening and v1.6 device recipes follow these priorities. Real tools, probes and isolation still require qualification on the assessment computer; this build has no hardware compatibility claim.</p><h3>Method reference</h3><p><a href="https://owasp.org/owasp-istg/" target="_blank" rel="noopener">OWASP IoT Security Testing Guide</a>. Starter procedures are adapted guidance, not a claim of exhaustive coverage or certification.</p></div>`)}
function preferencesDialog(){showDialog('Workspace preferences',`<div class="form-grid">${selectField('Theme','theme',['light','dark','contrast'],prefs.theme,true)}<label class="row"><input type="checkbox" name="advanced" ${prefs.advanced?'checked':''}> Advanced mode</label></div><p class="notice spaced">Advanced mode adds acquisition metadata to the working view. All saved evidence and report controls remain available in either mode.</p>`,data=>{prefs.theme=data.get('theme');prefs.advanced=data.has('advanced');render()})}
function exportProject(){if(!project)return;download(safeName(project.title)+'.probe.json',JSON.stringify(project,null,2));notify('Project exported with original evidence and baselines.')}
async function loadSample(){if(serial)throw Error('Disconnect serial before switching projects.');const next=await sampleProject();project=next;screen='boundary';subtab='board';selectedInterface=selectedSession=selectedArtifact=selectedBaseline='';modal.close();changed('Fictional sample assessment loaded.')}
function removeRecord(collection,id,label){ask('Remove '+label,`Remove this ${label.toLowerCase()} from the current assessment? Existing evidence and frozen baselines remain unchanged.`,()=>{project[collection]=project[collection].filter(x=>x.id!==id);changed(label+' removed.')},'Remove')}
async function handle(action,id,target){
 if(await advisoryUI.action(action,id)||await structuredUI.action(action,id)||await investigationUI.action(action,id)||await qualificationUI.action(action,id)||await companionUI.action(action,id)||await scans.action(action,id)||await debuggerUI.action(action,id)||await firmwareUI.action(action,id))return;
 switch(action){
 case 'boot-tab':bootTab=id;render();break;
 case 'nav':previewReport=false;screen=id;query='';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});break;
 case 'close':modal.close();break;
 case 'help':helpDialog();break;
 case 'offline-check':{if(!('serviceWorker'in navigator)||!isSecureContext){notify('Offline caching needs HTTPS or localhost. The current preview origin is not a secure context.');break;}const keys=await caches.keys();const key=keys.find(k=>k==='probe-v'+VERSION);if(!key){notify('Application cache is not installed yet. Reload once while online.');break;}const cache=await caches.open(key);const files=['./components.js','./advisories.js','./advisory-ui.js','./investigation.js','./investigation-ui.js','./ip.js','./','./index.html','./style.css','./app.js','./core.js','./serial.js','./network.js','./scan-ui.js','./companion-client.js','./companion-ui.js','./qualification.js','./qualification-ui.js','./debug-ui.js','./firmware.js','./firmware-compare.js','./firmware-compare-ui.js','./firmware-ui.js','./firmware-worker.js','./sample.js','./icon.svg','./manifest.webmanifest'];const results=await Promise.all(files.map(f=>cache.match(new URL(f,location.href))));const n=results.filter(Boolean).length;notify(n===files.length?`Offline application files ready (${n}/${files.length}). Export JSON for a separate project backup.`:`Offline cache incomplete (${n}/${files.length}). Reload while online.`);break;}
 case 'preferences':preferencesDialog();break;
 case 'project':projectDialog();break;
 case 'new':newDialog();break;
 case 'sample':if(project)ask('Load the sample assessment','The fictional sample will replace the active workspace. Export the current project first to keep it.',loadSample,'Load sample');else await loadSample();break;
 case 'import-project':pick('.json',async file=>{if(file.size>256*1024*1024)throw Error('Choose a project export under 256 MiB.');if(serial)throw Error('Disconnect serial before switching projects.');const next=validateProject(JSON.parse(await file.text()));notify('Verifying imported evidence hashes…');for(const e of next.evidence){const bytes=Uint8Array.from(atob(e.data.split(',')[1]),c=>c.charCodeAt(0));if(bytes.length!==e.size||bytes.length>32*1024*1024||await sha256(bytes)!==e.hash)throw Error('Evidence integrity check failed: '+e.title);}const load=()=>{project=next;for(const s of project.sessions)recoverCapture(s);selectedInterface=selectedSession=selectedArtifact=selectedBaseline='';screen='boundary';changed('Project imported. Evidence and baselines preserved.')};if(project)ask('Replace active workspace','Import this project in place of the current one? Export your current assessment first if you need to keep it.',load,'Import project');else load()});break;
 case 'export':exportProject();break;
 case 'scope':showDialog('Assessment title & scope',`<div class="form-grid">${field('Assessment title','title',project.title,'text',true)}${area('Scope, environment, access & exclusions','scope',project.scope)}</div>`,data=>{project.title=data.get('title');project.scope=data.get('scope');changed('Scope updated.')});break;
 case 'device':deviceDialog();break;
 case 'new-device':deviceDialog(true);break;
 case 'interface':interfaceDialog();break;
 case 'place-marker':placing=!placing;subtab='board';render();if(placing)notify('Click the board to place this marker. Numeric coordinates are available in Edit interface.');break;
 case 'interface-edit':interfaceDialog(selectedInterface);break;
 case 'select-interface':selectedInterface=id;render();break;
 case 'boundary-tab':subtab=id;render();break;
 case 'connection':connectionDialog(id);break;
 case 'remove-connection':removeRecord('connections',id,'Connection');break;
 case 'remove-interface':removeRecord('interfaces',id,'Interface');break;
 case 'observe-interface':screen='boottrace';query='';render();notify('Interface context retained. Connect an adapter or import its log.');break;
 case 'photo':pick('image/png,image/jpeg,image/webp',async f=>{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024)throw Error('Choose a PNG, JPEG or WebP image of 8 MiB or less.');device().photo=await bytesData(await f.arrayBuffer(),f.type);changed('Board photo saved. Marker positions remain editable.')});break;
 case 'clear-photo':device().photo='';changed('Illustrative board restored.');break;
 case 'evidence':evidenceDialog();break;
 case 'evidence-note':evidenceNote();break;
 case 'evidence-file':pick('',async file=>{const e=await evidenceFromFile(file,'Attachment');project.evidence.push(e);changed('Evidence original preserved.');evidenceDetail(e.id)});break;
 case 'evidence-detail':evidenceDetail(id);break;
 case 'evidence-download':{const e=project.evidence.find(x=>x.id===id);if(e?.data){const bytes=Uint8Array.from(atob(e.data.split(',')[1]),x=>x.charCodeAt(0));download(safeName(e.title),new Blob([bytes],{type:'application/octet-stream'}));}break;}
 case 'finding':findingDialog(id);break;
 case 'finding-from-evidence':findingDialog('',id);break;
 case 'delete-finding':removeRecord('findings',id,'Finding');break;
 case 'assumptions':assumptionsDialog();break;
 case 'assumption':assumptionDialog(id);break;
 case 'service':serviceDialog(id);break;
 case 'remove-service':removeRecord('services',id,'Service observation');break;
 case 'nmap':pick('.xml',importNmap);break;
 case 'network-tests':screen='assessment';assessmentTab='tests';render();break;
 case 'firmware':pick('',importFirmware);break;
 case 'import-sbom':pick('.json',importSbom);break;
 case 'connect':connectDialog();break;
 case 'serial-profile':profileDialog();break;
 case 'serial-history':historyDialog();break;
 case 'history-load':{const h=device().serialHistory?.[Number(id)];if(h){serialDraft={...h};modal.close();render();$('#serial-command')?.focus();}break;}
 case 'import-session':showDialog('Import a serial session',`<div class="stack">${button('Text log (.log / .txt)','import-log','','upload')}${button('PROBE capture (.json)','import-capture','','upload')}</div>`);break;
 case 'import-capture':modal.close();pick('.json',importCapture);break;
 case 'disconnect':await disconnectSerial();break;
 case 'import-log':modal.close();pick('.txt,.log,.csv',importLog);break;
 case 'select-session':selectedSession=id;query='';render();break;
 case 'toggle-hex':viewHex=!viewHex;render();break;
 case 'event':eventDialog();break;
 case 'session-evidence':await saveSessionEvidence();break;
 case 'session-download':sessionExportDialog();break;
 case 'session-transcript':{const s=currentSession();if(s)download(safeName(s.label)+'.log',transcript(s),'text/plain');break;}
 case 'capture-download':{const s=currentSession();if(s)download(safeName(s.label)+'.serial.json',JSON.stringify(await captureEnvelope(s),null,2));break;}
 case 'capture-rx':case 'capture-tx':{const s=currentSession();if(s)download(safeName(s.label)+(action==='capture-rx'?'.rx.bin':'.tx.bin'),rawCapture(s,action==='capture-rx'?'RX':'TX'),'application/octet-stream');break;}
 case 'compare-sessions':compareSessions();break;
 case 'test':testDialog(id);break;
 case 'assessment-tab':assessmentTab=id;render();break;
 case 'baseline':baselineDialog();break;
 case 'report':reportDialog();break;
 case 'report-preview':window.scrollTo(0,0);reportExcerpts=$('#report-excerpts')?.checked||false;previewReport=true;modal.close();render();break;
 case 'report-back':previewReport=false;render();break;
 case 'print':$('#print-report').innerHTML=reportBody(modal.open?$('#report-excerpts')?.checked:reportExcerpts);modal.close();window.print();break;
 }
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;handle(target.dataset.action,target.dataset.id||'',target).catch(err=>notify(err.message||'The action could not be completed.'))});
window.addEventListener('beforeunload',e=>{if(serial||saveState!=='Saved locally'&&project){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>{if(!serial)render()});window.addEventListener('offline',()=>{if(!serial)render()});
async function init(){settingsApply();try{db=await openDB();const stored=await readState();if(stored){project=validateProject(stored);if(project.sessions.reduce((n,s)=>n+Number(recoverCapture(s)),0))await save()}}catch(e){saveState='Save failed · export project';notify('Local storage could not be opened: '+e.message)}render();scans.init();if('serviceWorker'in navigator&&isSecureContext){try{await navigator.serviceWorker.register('./sw.js')}catch{notify('Offline cache could not be installed. The current workspace still works online.')}}}
init();
